hooks.command:
node -e "
const fs = require('fs');
const path = require('path');
const specPath = path.join(process.cwd(), '.agents', 'spec.md');
if (!fs.existsSync(specPath)) process.exit(0);
const content = fs.readFileSync(specPath, 'utf8');
const hasExecution = content.includes('## Execution Report');
const hasRefactoring = content.includes('## Refactoring Report');
const refactoringApproved = hasRefactoring && content.toLowerCase().includes('approved');
const hasTesting = content.includes('## Testing Report');
if (!hasExecution) {
  console.error('[eyc] Next step: run /coding to execute the implementation plan');
} else if (!hasRefactoring) {
  console.error('[eyc] Next step: run /refactor to review and propose safe improvements');
} else if (!refactoringApproved && !hasTesting) {
  console.error('[eyc] Next step: approve the refactoring plan, then run /coding — or run /testing to skip refactoring');
} else if (!hasTesting) {
  console.error('[eyc] Next step: run /testing to generate tests from acceptance criteria');
} else {
  console.error('[eyc] Pipeline complete. Run /archive <name> to preserve this spec.');
}
"
